"""Hand-authored DEMO sample: Plants (photosynthesis, transpiration, evapotranspiration) -> forest world
"Verdant Hollow - Bring the Rain Back". Fully authored WorldSpec (no assemble_world): 6 NPCs with
conversation-first lesson plans, one real mission, study cards, puzzles, side quests, glossary, review."""


def Q(id, prompt, choices, answer, accept, explain, hints):
    return dict(id=id, prompt=prompt, choices=choices, answerIndex=answer, accept=accept, explain=explain, hints=hints)


def B(id, obj, say, ask, rubric, hint, explain, fb, show=None):
    """fb = (prompt, [3 choices], answerIndex, [accept])"""
    p, ch, a, acc = fb
    d = dict(id=id, objectiveId=obj, say=say, ask=ask, rubric=rubric, hint=hint, explain=explain,
             fallback=Q(f'{id}-fb', p, ch, a, acc, explain, [hint]))
    if show:
        d['show'] = show
    return d


