def _quest(i, npc, zone_name, obj, cards, puzzles, prev, fx, title, collect=None):
    steps = [dict(id=f'q{i}-s1', kind='talk', targetId=npc['id'], text=f"Talk to {npc['name']} at {zone_name}")]
    for j, c in enumerate(cards):
        steps.append(dict(id=f'q{i}-st{j}', kind='study', targetId=c['id'], text=f'Study "{c["title"]}"'))
    steps.append(dict(id=f'q{i}-ex', kind='explain', targetId=npc['id'], text=f"Explain it to {npc['name']} in your own words"))
    if collect:
        steps.append(dict(id=f'q{i}-col', kind='collect', targetId=collect[0], count=collect[1], text=collect[2]))
    for j, p in enumerate(puzzles):
        steps.append(dict(id=f'q{i}-pz{j}', kind='puzzle', targetId=p['id'], text=f'Solve "{p["title"]}"'))
    return dict(id=f'q{i}', title=title, objectiveId=obj, prerequisiteIds=[prev] if prev else [], steps=steps, rewardEffectId=fx)


